INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0001','page_exam_hub','heading_2','{"text": "为什么要考"}',1,'2025-08-01T21:35:00+08:00','2025-08-01T21:35:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0002','page_exam_hub','paragraph','{"text": "在店里做了几年营业员，处方药区一直要等药师在场才能卖，很多顾客问用药问题我也只能转述说明书。想把证考下来，能自己审方，也算给这份工作一个交代。"}',2,'2025-08-01T21:35:00+08:00','2025-08-01T21:35:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0003','page_exam_hub','heading_2','{"text": "目前的情况"}',3,'2025-08-01T21:35:00+08:00','2025-08-01T21:35:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0004','page_exam_hub','paragraph','{"text": "大专药学，2021 年 7 月毕业，一直在同一家店，社保没断过。工作年限这块应该是够的，但具体怎么算要看今年的通知。"}',4,'2025-08-01T21:35:00+08:00','2025-08-01T21:35:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0005','page_exam_hub','paragraph','{"text": "上班是排班制，早班晚班夜班都有，夜班第二天上午基本报废。家里老人晚上要人照看，晚饭后到九点这段时间腾不出来。"}',5,'2025-08-01T21:35:00+08:00','2025-08-01T21:35:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0006','page_exam_hub','heading_2','{"text": "打算怎么复习"}',6,'2025-08-01T21:35:00+08:00','2025-08-01T21:35:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0007','page_exam_hub','paragraph','{"text": "四科里药综和法规最没底。法规每年都在改，去年买的旧课基本白搭，今年得看清楚版本再买。"}',7,'2025-08-01T21:35:00+08:00','2025-08-01T21:35:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0008','page_exam_hub','paragraph','{"text": "打算按科目分块，一次只推一科，做完配套题再往下走。不熬夜，熬了第二天上班也顶不住。"}',8,'2025-08-01T21:35:00+08:00','2025-08-01T21:35:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0009','page_exam_hub','heading_2','{"text": "记一下"}',9,'2025-08-01T21:35:00+08:00','2025-08-01T21:35:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0010','page_exam_hub','to_do','{"text": "问一下 HR 工作年限证明怎么开"}',10,'2025-08-01T21:35:00+08:00','2025-08-01T21:35:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0011','page_exam_hub','to_do','{"text": "毕业证扫描件找出来"}',11,'2025-08-01T21:35:00+08:00','2025-08-01T21:35:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0012','page_exam_hub','to_do','{"text": "报名通知出来后核对一遍报考条件"}',12,'2025-08-01T21:35:00+08:00','2025-08-01T21:35:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0013','page_exam_hub','paragraph','{"text": "预算：课程这块最多留一千八，再多家里那边不好交代。"}',13,'2025-08-01T21:35:00+08:00','2025-08-01T21:35:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0014','page_shift_notes','paragraph','{"text": "04月07日 早班客流集中在开门后一小时，慢病取药的老人多，处方审核排队。库存表当班更新完毕。"}',14,'2026-04-07T21:10:00+08:00','2026-04-07T21:10:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0015','page_shift_notes','paragraph','{"text": "04月09日 晚班收尾要盘点处方药柜，数量对不上要写情况说明。当班处方 34 张。"}',15,'2026-04-09T16:10:00+08:00','2026-04-09T16:10:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0016','page_shift_notes','paragraph','{"text": "04月10日 夜班基本只有急需药，凌晨两点后几乎没人，但不能睡。系统里补录了三条。"}',16,'2026-04-10T21:10:00+08:00','2026-04-10T21:10:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0017','page_shift_notes','paragraph','{"text": "04月12日 今天有顾客拿外院处方来配药，医院章不清楚，让他回去重开。交接时清点无误。"}',17,'2026-04-12T02:10:00+08:00','2026-04-12T02:10:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0018','page_shift_notes','paragraph','{"text": "04月13日 换季这段时间呼吸道用药走得快，货架天天要补。"}',18,'2026-04-13T21:10:00+08:00','2026-04-13T21:10:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0019','page_shift_notes','paragraph','{"text": "04月15日 医保刷卡系统上午卡了半小时，只能先手工登记。当班处方 23 张。"}',19,'2026-04-15T02:10:00+08:00','2026-04-15T02:10:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0020','page_shift_notes','paragraph','{"text": "04月16日 有个顾客要买头孢，问了才知道在喝酒，劝住了。"}',20,'2026-04-16T01:10:00+08:00','2026-04-16T01:10:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0021','page_shift_notes','paragraph','{"text": "04月17日 小孩退热的剂型问得最多，滴剂和混悬液家长分不清。交接时清点无误。"}',21,'2026-04-17T18:10:00+08:00','2026-04-17T18:10:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0022','page_shift_notes','paragraph','{"text": "04月19日 店长说下个月要迎检，处方留存和温湿度记录都得补齐。"}',22,'2026-04-19T11:10:00+08:00','2026-04-19T11:10:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0023','page_shift_notes','paragraph','{"text": "04月20日 冷链的胰岛素今天到货，温度记录单跟着一起签收。库存表当班更新完毕。"}',23,'2026-04-20T06:10:00+08:00','2026-04-20T06:10:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0024','page_shift_notes','paragraph','{"text": "04月21日 老人问降压药能不能自己减量，跟他说了必须问医生。库存表当班更新完毕。"}',24,'2026-04-21T23:10:00+08:00','2026-04-21T23:10:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0025','page_shift_notes','paragraph','{"text": "04月22日 今天补了一批中成药标签，之前的批号打印不清。有两笔退货，都登记了。"}',25,'2026-04-22T18:10:00+08:00','2026-04-22T18:10:00+08:00');
