INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0148','page_drug_cards','bulleted_list_item','{"text": "二甲双胍：一线降糖药，主要不良反应是胃肠道反应，肾功能不全者慎用，造影检查前需暂停。"}',148,'2026-04-20T20:05:00+08:00','2026-04-20T20:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0149','page_drug_cards','bulleted_list_item','{"text": "阿托伐他汀：晚上服用效果较好，注意肌痛和转氨酶升高，与克拉霉素合用风险增加。"}',149,'2026-04-22T01:05:00+08:00','2026-04-22T01:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0150','page_drug_cards','bulleted_list_item','{"text": "氨氯地平：长效钙拮抗剂，常见踝部水肿，不需随餐服用。"}',150,'2026-04-23T00:05:00+08:00','2026-04-23T00:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0151','page_drug_cards','bulleted_list_item','{"text": "华法林：治疗窗窄，需监测 INR，与很多药物和食物有相互作用，绿叶菜要保持稳定摄入。"}',151,'2026-04-23T23:05:00+08:00','2026-04-23T23:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0152','page_drug_cards','bulleted_list_item','{"text": "奥美拉唑：质子泵抑制剂，餐前半小时服用，长期使用注意维生素 B12 和镁的缺乏。"}',152,'2026-04-24T22:05:00+08:00','2026-04-24T22:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0153','page_drug_cards','bulleted_list_item','{"text": "布洛芬：解热镇痛，消化道溃疡者慎用，与阿司匹林合用可能影响后者抗血小板作用。"}',153,'2026-04-26T03:05:00+08:00','2026-04-26T03:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0154','page_drug_cards','bulleted_list_item','{"text": "头孢曲松：用药期间及停药后一周内禁酒，避免双硫仑样反应。"}',154,'2026-04-27T10:05:00+08:00','2026-04-27T10:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0155','page_drug_cards','bulleted_list_item','{"text": "左氧氟沙星：注意肌腱炎风险，18 岁以下不推荐，避免与含金属离子的药同服。"}',155,'2026-04-28T23:05:00+08:00','2026-04-28T23:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0156','page_drug_cards','bulleted_list_item','{"text": "沙丁胺醇：急性发作缓解用药，不是长期控制药，用量突然增加提示病情不稳。"}',156,'2026-04-30T06:05:00+08:00','2026-04-30T06:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0157','page_drug_cards','bulleted_list_item','{"text": "胰岛素：未开封冷藏，开封后室温可放一个月，不能冷冻。"}',157,'2026-05-01T13:05:00+08:00','2026-05-01T13:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0158','page_drug_cards','bulleted_list_item','{"text": "氯雷他定：第二代抗组胺药，嗜睡较轻，但仍需提醒驾驶注意。"}',158,'2026-05-02T12:05:00+08:00','2026-05-02T12:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0159','page_drug_cards','bulleted_list_item','{"text": "硝酸甘油：舌下含服，开封后有效期缩短，需避光保存。"}',159,'2026-05-04T01:05:00+08:00','2026-05-04T01:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0160','page_drug_cards','bulleted_list_item','{"text": "阿司匹林肠溶片：不能掰开或嚼碎，餐前空腹服用吸收较好。"}',160,'2026-05-05T00:05:00+08:00','2026-05-05T00:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0161','page_drug_cards','bulleted_list_item','{"text": "氨溴索：祛痰药，不建议与强力镇咳药同时使用。"}',161,'2026-05-05T23:05:00+08:00','2026-05-05T23:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0162','page_drug_cards','bulleted_list_item','{"text": "蒙脱石散：需空腹服用，与其他药物间隔两小时以上。"}',162,'2026-05-07T06:05:00+08:00','2026-05-07T06:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0163','page_drug_cards','bulleted_list_item','{"text": "二甲双胍：一线降糖药，主要不良反应是胃肠道反应，肾功能不全者慎用，造影检查前需暂停。（配伍要留意）"}',163,'2026-05-08T19:05:00+08:00','2026-05-08T19:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0164','page_drug_cards','bulleted_list_item','{"text": "阿托伐他汀：晚上服用效果较好，注意肌痛和转氨酶升高，与克拉霉素合用风险增加。（上次被问住了）"}',164,'2026-05-10T08:05:00+08:00','2026-05-10T08:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0165','page_drug_cards','bulleted_list_item','{"text": "氨氯地平：长效钙拮抗剂，常见踝部水肿，不需随餐服用。（店里问得多）"}',165,'2026-05-11T15:05:00+08:00','2026-05-11T15:05:00+08:00');
