INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0170','page_drug_cards','bulleted_list_item','{"text": "左氧氟沙星：注意肌腱炎风险，18 岁以下不推荐，避免与含金属离子的药同服。（店里问得多）"}',170,'2026-05-18T02:05:00+08:00','2026-05-18T02:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0171','page_drug_cards','bulleted_list_item','{"text": "沙丁胺醇：急性发作缓解用药，不是长期控制药，用量突然增加提示病情不稳。（配伍要留意）"}',171,'2026-05-19T15:05:00+08:00','2026-05-19T15:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0172','page_drug_cards','bulleted_list_item','{"text": "胰岛素：未开封冷藏，开封后室温可放一个月，不能冷冻。（重点记）"}',172,'2026-05-20T14:05:00+08:00','2026-05-20T14:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0173','page_drug_cards','bulleted_list_item','{"text": "氯雷他定：第二代抗组胺药，嗜睡较轻，但仍需提醒驾驶注意。（配伍要留意）"}',173,'2026-05-21T21:05:00+08:00','2026-05-21T21:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0174','page_drug_cards','bulleted_list_item','{"text": "硝酸甘油：舌下含服，开封后有效期缩短，需避光保存。（重点记）"}',174,'2026-05-23T10:05:00+08:00','2026-05-23T10:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0175','page_drug_cards','bulleted_list_item','{"text": "阿司匹林肠溶片：不能掰开或嚼碎，餐前空腹服用吸收较好。（配伍要留意）"}',175,'2026-05-24T23:05:00+08:00','2026-05-24T23:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0176','page_drug_cards','bulleted_list_item','{"text": "氨溴索：祛痰药，不建议与强力镇咳药同时使用。（重点记）"}',176,'2026-05-25T22:05:00+08:00','2026-05-25T22:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0177','page_drug_cards','bulleted_list_item','{"text": "蒙脱石散：需空腹服用，与其他药物间隔两小时以上。（店里问得多）"}',177,'2026-05-27T11:05:00+08:00','2026-05-27T11:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0178','page_drug_cards','bulleted_list_item','{"text": "二甲双胍：一线降糖药，主要不良反应是胃肠道反应，肾功能不全者慎用，造影检查前需暂停。（上次被问住了）"}',178,'2026-05-28T10:05:00+08:00','2026-05-28T10:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0179','page_drug_cards','bulleted_list_item','{"text": "阿托伐他汀：晚上服用效果较好，注意肌痛和转氨酶升高，与克拉霉素合用风险增加。（上次被问住了）"}',179,'2026-05-29T23:05:00+08:00','2026-05-29T23:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0180','page_drug_cards','bulleted_list_item','{"text": "氨氯地平：长效钙拮抗剂，常见踝部水肿，不需随餐服用。（重点记）"}',180,'2026-05-31T04:05:00+08:00','2026-05-31T04:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0181','page_drug_cards','bulleted_list_item','{"text": "华法林：治疗窗窄，需监测 INR，与很多药物和食物有相互作用，绿叶菜要保持稳定摄入。（配伍要留意）"}',181,'2026-06-01T03:05:00+08:00','2026-06-01T03:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0182','page_drug_cards','bulleted_list_item','{"text": "奥美拉唑：质子泵抑制剂，餐前半小时服用，长期使用注意维生素 B12 和镁的缺乏。（上次被问住了）"}',182,'2026-06-02T10:05:00+08:00','2026-06-02T10:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0183','page_drug_cards','bulleted_list_item','{"text": "布洛芬：解热镇痛，消化道溃疡者慎用，与阿司匹林合用可能影响后者抗血小板作用。（配伍要留意）"}',183,'2026-06-03T09:05:00+08:00','2026-06-03T09:05:00+08:00');
INSERT INTO blocks (block_id,parent_page_id,type,content_json,position,created_time,last_edited_time) VALUES ('blk_0184','page_drug_cards','bulleted_list_item','{"text": "头孢曲松：用药期间及停药后一周内禁酒，避免双硫仑样反应。（上次被问住了）"}',184,'2026-06-04T16:05:00+08:00','2026-06-04T16:05:00+08:00');
